targets.root_selector:
(
  $daily := $sort($map($distinct(result.costs.date), function($d) { { "date": $d, "totalCHC": $sum($$.result.costs[date = $d].totalCHC) } }), function($a, $b) { $a.date > $b.date });
  $today := $substringBefore($now(), "T");
  $full := $daily[date < $today];
  $n := $count($full);
  $last := $n > 3 ? $full[[($n - 3)..($n - 1)]] : $full;
  $avg := $count($last) > 0 ? $average($last.totalCHC) : null;
  $left := 300 - $sum($daily.totalCHC);
  $end := "2026-11-23";
  $day := 86400000;
  $text := $count($daily) = 0 ? "Not available" :
    $left <= 0 ? "▲ Credits used up" :
    $avg = null ? "Not available" :
    $avg <= 0 ? "✓ No spend in the last full days" :
    (
      $out := $fromMillis($toMillis($today) + $floor($left / $avg) * $day, "[Y0001]-[M01]-[D01]");
      $diff := $round(($toMillis($end) - $toMillis($out)) / $day);
      $diff > 0 ? "▲ " & $out & " · " & $diff & " days before trial end" :
      $diff = 0 ? "✓ " & $out & " · on the trial end date" :
      "✓ " & $out & " · " & (-$diff) & " days after trial end"
    );
  $map([1], function($x) { { "run_out": $text } })
)
